{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to eliminate a problem identified during an earlier execution step, such as an observed build/test failure, a missing prerequisite, or a detected source-level incompatibility.",
      "source_description": "An earlier identified problem: an observed execution failure or error, a missing dependency/tool, or a detected defective or incompatible pattern in source code.",
      "target_description": "A subsequent agent action intended to resolve that problem, such as modifying source code, correcting configuration, installing a prerequisite, or retrying the previously failed operation."
    },
    {
      "name": "VERIFIES_OUTCOME",
      "definition": "A subsequent check, test, or example execution is performed to determine whether an earlier operation produced the expected result or successfully resolved the problem.",
      "source_description": "A subsequent verification action (re-scan, test run, or example execution) executed to confirm an earlier result.",
      "target_description": "An earlier operation result, produced artifact, or applied repair whose correctness or completeness is being confirmed."
    },
    {
      "name": "USES_PRIOR_RESULT_AS_INPUT",
      "definition": "A subsequent agent action consumes data, identifiers, patterns, or artifacts obtained from an earlier tool result as an input or parameter of that action, rather than merely reacting to a problem.",
      "source_description": "An earlier tool result that provides data, identifiers, code patterns, or artifacts.",
      "target_description": "A subsequent agent action that incorporates that data as an argument, pattern, or input to its operation."
    }
  ]
}

